function eventRegionsForCountry(country:string) {
  if (country === 'All') return vexEventRegions;
  const groups:Record<string,string[]> = { 'United States': usEventRegions, Canada: canadaEventRegions, China: chinaEventRegions, Europe: europeEventRegions, 'Asia Pacific': asiaPacificEventRegions };
  const aliases:Record<string,string> = { Taiwan: 'Chinese Taipei', Georgia: 'Georgia- Country' };
  const matches = groups[country] ?? [aliases[country] ?? country].filter(region => vexEventRegions.includes(region));
  return ['All', ...matches];
}

