function AppLogo() { return <span className="flex items-center gap-2 font-black tracking-[-.04em]"><span className="grid h-8 w-8 place-items-center bg-[#ed2b3a] text-sm italic">V</span><span className="text-xl">VEX<span className="text-[#ed2b3a]">RANK</span></span></span>; }
function Trend({ value }: { value: number }) { return value > 0 ? <span className="inline-flex items-center gap-0.5 text-emerald-400"><ArrowUp className="h-3 w-3" />{value}</span> : value < 0 ? <span className="text-rose-400">{value}</span> : <span className="text-white/25">—</span>; }
function liveTeamsLabel(rows:any[]) { return rows[0]?.matches ? 'Provisional live VCR' : 'Loading live VCR'; }
function Tier({ value='Official' }: { value?: string }) { const cls = value.includes('Gold') || value === 'Worlds' ? 'bg-amber-400/10 text-amber-300 border-amber-400/20' : value.includes('Silver') ? 'bg-slate-300/10 text-slate-200 border-slate-300/20' : value.includes('Bronze') ? 'bg-orange-400/10 text-orange-300 border-orange-400/20' : 'bg-white/5 text-white/55 border-white/10'; return <span className={`inline-flex border px-2 py-1 text-[10px] font-black uppercase tracking-wider ${cls}`}>{value}</span>; }
function EventStatus({ value='Upcoming' }: { value?: string }) { const normalized=value.toLowerCase();const cls=normalized==='cancelled'?'text-[#ff3347]':normalized==='upcoming'?'text-sky-400':'text-emerald-400';return <span className={`text-[10px] font-bold uppercase tracking-wider ${cls}`}>{value}</span>; }

export default function Home() {
  const [view, setView] = useState<View>('home');
  const [mobile, setMobile] = useState(false);
  const [globalSearch, setGlobalSearch] = useState('');
  const [eventSearch, setEventSearch] = useState('');
  const [region, setRegion] = useState('All');
  const [eventClass, setEventClass] = useState('All');
  const [format, setFormat] = useState('All');
  const [time, setTime] = useState('All events');
  const [grade, setGrade] = useState('All');
  const [eventExtras, setEventExtras] = useState({ season: '2026–27: Override', level: 'All', from: '', to: '', eventRegion: 'All', city: '', affiliation: '', registrationOpen: false, spotsOpen: false, worldQualifier: false, girlPowered: false, includeCanceled: false });
  const [liveEvents, setLiveEvents] = useState<any[]>([]);
  const [eventsError,setEventsError]=useState('');
  const [eventsLoading,setEventsLoading]=useState(true);
  const [eventsRetry,setEventsRetry]=useState(0);
  const [eventsLive, setEventsLive] = useState(false);
  const [liveTeams, setLiveTeams] = useState<any[]>([]);
  const [rankingsMeta, setRankingsMeta] = useState<any>(null);
  const [rankingsError,setRankingsError]=useState('');
  const [rankingsRetry,setRankingsRetry]=useState(0);
  const [teamSearch, setTeamSearch] = useState('');
  const [teamRegion, setTeamRegion] = useState('All');
  const [rankingRange, setRankingRange] = useState('All');
  const [rankingViewState,setRankingViewState]=useState({season:'2026–27 Override',country:'All',region:'All',grade:'All teams',search:'',visibleCount:100});
  const [selectedTeam, setSelectedTeam] = useState<any>({number:'',name:''});
  const [teamReturnView,setTeamReturnView]=useState<View>('teams');
  const [selectedEvent, setSelectedEvent] = useState<any>({});
  const [navigationRestored,setNavigationRestored]=useState(false);

  useEffect(()=>{
    try {
      const saved=JSON.parse(sessionStorage.getItem('vexrank-navigation')??'null');
      if(saved){if(saved.view)setView(saved.view);if(saved.selectedTeam)setSelectedTeam(saved.selectedTeam);if(saved.selectedEvent)setSelectedEvent(saved.selectedEvent);if(saved.eventSearch!=null)setEventSearch(saved.eventSearch);if(saved.teamSearch!=null)setTeamSearch(saved.teamSearch);if(saved.region)setRegion(saved.region);if(saved.eventClass)setEventClass(saved.eventClass);if(saved.format)setFormat(saved.format);if(saved.time)setTime(saved.time);if(saved.grade)setGrade(saved.grade);if(saved.eventExtras)setEventExtras(saved.eventExtras);if(saved.teamRegion)setTeamRegion(saved.teamRegion);if(saved.rankingRange)setRankingRange(saved.rankingRange);if(saved.rankingViewState)setRankingViewState(saved.rankingViewState);if(saved.teamReturnView)setTeamReturnView(saved.teamReturnView);requestAnimationFrame(()=>requestAnimationFrame(()=>window.scrollTo(0,saved.scrollY??0)))}
    } catch {}
    setNavigationRestored(true);
  },[]);

  useEffect(()=>{
    if(!navigationRestored)return;
    const save=()=>{try{sessionStorage.setItem('vexrank-navigation',JSON.stringify({view,selectedTeam,selectedEvent,eventSearch,teamSearch,region,eventClass,format,time,grade,eventExtras,teamRegion,rankingRange,rankingViewState,teamReturnView,scrollY:window.scrollY}));}catch{}};
    save();window.addEventListener('pagehide',save);return()=>window.removeEventListener('pagehide',save);
  },[navigationRestored,view,selectedTeam,selectedEvent,eventSearch,teamSearch,region,eventClass,format,time,grade,eventExtras,teamRegion,rankingRange,rankingViewState,teamReturnView]);

  useEffect(() => {
    let active = true;
    const seasonId=({'2026–27: Override':'204','2025–26: Push Back':'197','2024–25: High Stakes':'190','2023–24: Over Under':'181'} as Record<string,string>)[eventExtras.season]??'204';
    setEventsLoading(true);setEventsError('');setLiveEvents([]);setEventsLive(false);
    fetch(`/api/events?season=${seasonId}&classification=v49`).then(response => response.ok ? response.json() : Promise.reject()).then((payload:any) => {
      if (active && Array.isArray(payload.events)) { setLiveEvents(payload.events); setEventsLive(true); }
    }).catch(() => {if(active)setEventsError('Events could not be loaded. Please retry.');}).finally(()=>{if(active)setEventsLoading(false)});
    return () => { active = false; };
  }, [eventExtras.season,eventsRetry]);

  useEffect(()=>{
    if(!['home','rankings','stats','teams'].includes(view)||rankingsMeta)return;
    let active=true;
    setRankingsError('');
    fetch('/api/rankings?data=v49').then(response=>response.ok?response.json():Promise.reject()).then((payload:any)=>{if(active&&Array.isArray(payload.rankings)){setLiveTeams(payload.rankings);setRankingsMeta(payload)}}).catch(()=>{if(active)setRankingsError('Rankings are temporarily unavailable. Please retry.');});
    return()=>{active=false};
  },[rankingsRetry,view]);

  const eventRows = liveEvents;
  const teamRows = liveTeams;

  const go = (next: View) => { setView(next); setMobile(false); window.scrollTo({ top: 0, behavior: 'smooth' }); };
  const openTeam = (team: any) => { prefetchTeam(team.number,team.seasonId,team.id);setSelectedTeam(team); setTeamReturnView(view); go('team'); };
  const openEvent = (event:any) => { prefetchEvent(event.id);setSelectedEvent(event); go('event'); };
  const submitGlobal = () => { const q = globalSearch.trim().toLowerCase(); const match = teamRows.find(t => t.number.toLowerCase() === q || t.name.toLowerCase().includes(q)); if (match) openTeam(match); else if (q) { setTeamSearch(globalSearch); go('teams'); } };

  const shownEvents = useMemo(() => eventRows.filter((e:any) => {
    if (!eventExtras.includeCanceled && /cancell?ed/i.test(e.status ?? e.name)) return false;
    const level = e.levelClass ?? (e.id === 'worlds' ? 'World Championship' : e.class === 'Signature' ? 'Signature Event' : e.id === 'singapore' ? 'Event Region Championship' : 'None');
    const eventRegion = e.eventRegion ?? ({ kalahari: 'Ohio', canadian: 'Ontario', riverbots: 'Kentucky', pacific: 'British Columbia (BC)', singapore: 'Singapore', winter: 'Unassigned', texas: 'Texas - Region 3', worlds: 'Missouri' } as Record<string,string>)[e.id];
    const eventType = e.eventType ?? (e.id === 'singapore' ? 'Invitational Tournament' : e.id === 'pacific' ? 'School-Based Tournament' : e.id === 'winter' ? 'Live Remote Skills' : 'Open Tournament');
    const eventFormats = e.formats ?? [e.format, ...(e.status === 'Invitational' ? ['Invitational'] : []), ...(e.id === 'winter' ? ['Skills Only'] : [])];
    const worldQualifier = e.worldQualifier ?? false;
    const girlPowered = /girl powered/i.test(e.name);
    const today=new Date().toISOString().slice(0,10);const next30=new Date(Date.now()+30*86400000).toISOString().slice(0,10);const normalize=(value:string)=>value.toLowerCase().replace(/[^a-z0-9]/g,'');const seasonLabel=String(e.season??'').includes('2026-2027')||!e.season?'2026–27: Override':String(e.season??'').includes('2025-2026')?'2025–26: Push Back':String(e.season??'').includes('2024-2025')?'2024–25: High Stakes':String(e.season??'').includes('2023-2024')?'2023–24: Over Under':e.season;
    return (!eventSearch || `${e.name} ${e.city}`.toLowerCase().includes(eventSearch.toLowerCase())) && (region === 'All' || normalize(e.region) === normalize(region)) && (eventExtras.season==='All'||seasonLabel===eventExtras.season) && (eventClass === 'All' || eventType === eventClass) && (format === 'All' || eventFormats.includes(format)) && (grade === 'All' || e.grade === grade || e.grade === 'Mixed') && (time === 'All events' || (time === 'Upcoming only'&&e.date>=today) || (time === 'Next 30 days' && e.date>=today&&e.date<=next30)) && (eventExtras.level === 'All' || level === eventExtras.level) && (!eventExtras.from || e.date >= eventExtras.from) && (!eventExtras.to || e.date <= eventExtras.to) && (eventExtras.eventRegion === 'All' || normalize(eventRegion)===normalize(eventExtras.eventRegion)) && (!eventExtras.city || e.city.toLowerCase().includes(eventExtras.city.toLowerCase())) && (!eventExtras.affiliation || e.name.toLowerCase().includes(eventExtras.affiliation.toLowerCase())) && (!eventExtras.registrationOpen || e.status === 'Registration open') && (!eventExtras.spotsOpen || e.status === 'Registration open') && (!eventExtras.worldQualifier || worldQualifier) && (!eventExtras.girlPowered || girlPowered);
  }), [eventRows, eventSearch, region, eventClass, format, time, grade, eventExtras]);
  const shownTeams = useMemo(() => teamRows.filter(t => (!teamSearch || `${t.number} ${t.name}`.toLowerCase().includes(teamSearch.toLowerCase())) && (teamRegion === 'All' || t.country === teamRegion) && (rankingRange === 'All' || (rankingRange === 'Top 5' && t.rank <= 5) || (rankingRange === 'Top 10' && t.rank <= 10) || (rankingRange === '11–50' && t.rank >= 11))), [teamRows, teamSearch, teamRegion, rankingRange]);


  return <main className="min-h-screen bg-[#090b0f] text-[#f4f5f7]">
    <header className="sticky top-0 z-50 border-b border-white/10 bg-[#0d1015]/95 backdrop-blur-xl">
      <div className="mx-auto flex h-16 max-w-[1440px] items-center gap-8 px-5 lg:px-8">
        <button aria-label="Go home" onClick={() => go('home')}><AppLogo /></button>
        <nav className="hidden h-full items-center gap-7 text-sm font-semibold text-white/55 md:flex">
          {([['events','Events'],['rankings','Rankings'],['stats','Stat leaders'],['teams','Teams']] as const).map(([id,label]) => <button key={id} onClick={() => go(id)} className={`h-full border-b-2 transition ${view === id || (view === 'team' && id === teamReturnView) ? 'border-[#ed2b3a] text-white' : 'border-transparent hover:text-white'}`}>{label}</button>)}
        </nav>
        <form onSubmit={e => { e.preventDefault(); submitGlobal(); }} className="ml-auto hidden w-full max-w-sm items-center gap-2 border border-white/10 bg-white/5 px-3 sm:flex">
          <Search className="h-4 w-4 text-white/35" /><input value={globalSearch} onChange={e => setGlobalSearch(e.target.value)} className="h-9 w-full border-0 bg-transparent px-0 text-sm text-white outline-none placeholder:text-white/30" placeholder="Search team number or name" aria-label="Search teams" />
        </form>
        <button className="ml-auto md:hidden" onClick={() => setMobile(!mobile)} aria-label="Toggle navigation">{mobile ? <X /> : <Menu />}</button>
      </div>
      {mobile && <nav className="border-t border-white/10 bg-[#0d1015] p-4 md:hidden">{(['events','rankings','stats','teams'] as View[]).map(v => <button key={v} onClick={() => go(v)} className="block w-full border-b border-white/10 px-2 py-3 text-left font-bold capitalize">{v === 'stats' ? 'Stat leaders' : v}</button>)}</nav>}
    </header>

    {view === 'home' && <HomeView go={go} openTeam={openTeam} openEvent={openEvent} eventRows={eventRows} teamRows={teamRows} />}
    {view === 'events' && <EventsView loading={eventsLoading} error={eventsError} retry={()=>setEventsRetry(value=>value+1)} results={shownEvents} live={eventsLive} openEvent={openEvent} search={eventSearch} setSearch={setEventSearch} filters={{region,eventClass,format,time,grade}} setters={{setRegion,setEventClass,setFormat,setTime,setGrade}} extras={eventExtras} setExtras={setEventExtras} />}
    {view === 'event' && <EventInfoView key={selectedEvent.id} event={selectedEvent} goBack={() => go('events')} openTeam={openTeam} />}
    {(view==='rankings'||view==='stats'||view==='home')&&rankingsError&&<LoadError message={rankingsError} retry={()=>setRankingsRetry(value=>value+1)} />}
    {view === 'rankings' && <RankingsView teams={teamRows} meta={rankingsMeta} openTeam={openTeam} savedState={rankingViewState} setSavedState={setRankingViewState} />}
    {view === 'stats' && <StatRankingsView teams={teamRows} openTeam={openTeam} />}
    {view === 'teams' && <TeamsView results={shownTeams} search={teamSearch} setSearch={setTeamSearch} region={teamRegion} setRegion={setTeamRegion} range={rankingRange} setRange={setRankingRange} openTeam={openTeam} />}
    {view === 'team' && <TeamView key={`${selectedTeam.number}:${selectedTeam.seasonId??selectedTeam.season??''}`} team={selectedTeam} goBack={() => go(teamReturnView)} backLabel={teamReturnView==='rankings'?'rankings':teamReturnView==='stats'?'stat leaders':teamReturnView==='events'||teamReturnView==='event'?'event':'teams'} openEvent={openEvent} />}

    <footer className="mt-16 border-t border-white/10 bg-[#0d1015]"><div className="mx-auto flex max-w-[1440px] flex-col gap-5 px-5 py-8 text-xs text-white/35 sm:flex-row sm:items-center lg:px-8"><AppLogo /><p>Independent V5RC analytics using official Event.VEX results.</p><p className="sm:ml-auto">VCR model · 2026–27 season</p></div></footer>
  </main>;
}

function HomeView({ go, openTeam, openEvent, eventRows, teamRows }: { go: (v: View) => void; openTeam: (t:any) => void; openEvent:(event:any)=>void; eventRows: typeof events; teamRows:any[] }) {
  const upcomingSignatures=eventRows.filter((event:any)=>event.class==='Signature Event'&&!/cancell?ed/i.test(event.status)&&event.date>=new Date().toISOString().slice(0,10));
  const bestByDate=new Map<string,any>();upcomingSignatures.forEach((event:any)=>{const current=bestByDate.get(event.date);if(!current||(event.rankScore??0)>(current.rankScore??0))bestByDate.set(event.date,event)});
  const featured=[...bestByDate.values()].sort((a:any,b:any)=>a.date.localeCompare(b.date)||(b.rankScore??0)-(a.rankScore??0));
  const primaryEvent = featured[0];
  return <>
    <section className="mx-auto max-w-[1440px] px-5 pb-8 pt-10 lg:px-8">
      <div className="mb-6 flex items-end justify-between gap-4"><div><p className="mb-2 text-xs font-bold uppercase tracking-[.18em] text-[#ed2b3a]">2026–27 V5RC season</p><h1 className="text-3xl font-black tracking-[-.04em] sm:text-5xl">The competition starts here.</h1></div><button onClick={() => go('events')} className="hidden items-center gap-2 text-sm font-bold text-white/60 hover:text-white sm:flex">Browse all events <ArrowUpRight className="h-4 w-4" /></button></div>
      <div className="grid gap-4 lg:grid-cols-[1.65fr_1fr]">
        {primaryEvent?<article className="relative min-h-[360px] overflow-hidden border border-white/10 bg-[radial-gradient(circle_at_85%_20%,rgba(237,43,58,.25),transparent_32%),linear-gradient(135deg,#171b22,#0c0f14)] p-7 sm:p-9"><div className="absolute right-5 top-4 text-[150px] font-black leading-none text-white/[.025]">01</div><Tier value={primaryEvent.tier} /><div className="mt-16 max-w-xl"><p className="mb-3 flex items-center gap-2 text-sm font-semibold text-white/55"><CalendarDays className="h-4 w-4 text-[#ed2b3a]" /> {new Date(`${primaryEvent.date}T12:00:00`).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'}).toUpperCase()}</p><h2 className="text-4xl font-black tracking-[-.04em] sm:text-6xl">{primaryEvent.name}</h2><p className="mt-4 flex items-center gap-2 text-sm text-white/55"><MapPin className="h-4 w-4" /> {primaryEvent.city}{primaryEvent.teams ? ` · ${primaryEvent.teams} teams` : ''} · {primaryEvent.grade}</p><p className="mt-2 text-xs text-white/35">{primaryEvent.rankLocked?'Event rank locked':'Rank locks'} · {new Date(primaryEvent.rankLockDate).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</p></div><button onClick={() => openEvent(primaryEvent)} className="mt-8 inline-flex h-11 items-center gap-2 bg-white px-5 text-sm font-black text-black hover:bg-[#ed2b3a] hover:text-white">View event <ArrowUpRight className="h-4 w-4" /></button></article>:<Empty text="No upcoming Signature Events are currently listed." />}
        <aside className="border border-white/10 bg-[#101319]"><SectionTitle eyebrow={liveTeamsLabel(teamRows)} title="World ranking" icon={<Trophy />} />{teamRows.slice(0,5).map(t => <button onClick={() => openTeam(t)} key={t.number} className="grid w-full grid-cols-[32px_1fr_auto] items-center gap-3 border-b border-white/[.07] px-5 py-3.5 text-left hover:bg-white/[.04]"><b className="text-lg text-white/25">{String(t.rank).padStart(2,'0')}</b><span><b className="block">{t.number}</b><small className="block truncate text-white/40">{t.name}</small></span><span className="text-right"><b className="block font-mono">{t.rating}</b><small className="text-white/30">±{t.confidence ?? '—'}</small></span></button>)}<button onClick={() => go('rankings')} className="flex w-full items-center justify-center gap-2 px-5 py-4 text-xs font-black uppercase tracking-wider text-white/55 hover:text-white">Full ranking <ArrowRight className="h-3.5 w-3.5" /></button></aside>
      </div>
    </section>
    <section className="mx-auto max-w-[1440px] px-5 py-8 lg:px-8"><div className="mb-5 flex items-center justify-between"><div><p className="text-xs font-black uppercase tracking-[.18em] text-[#ed2b3a]">On the calendar</p><h2 className="mt-1 text-2xl font-black">Upcoming Signature Events</h2></div><button onClick={() => go('events')} className="text-sm font-bold text-white/50 hover:text-white">Browse calendar</button></div><div className="grid gap-3 md:grid-cols-3">{featured.slice(0,3).map(e => <button onClick={() => openEvent(e)} key={e.id} className="group flex border border-white/10 bg-[#101319] text-left hover:-translate-y-0.5 hover:border-white/25"><div className="grid w-20 place-items-center border-r border-white/10 bg-white/[.025] py-5 text-center"><span><small className="block font-bold text-[#ed2b3a]">{new Date(`${e.date}T12:00:00`).toLocaleString('en',{month:'short'}).toUpperCase()}</small><b className="block text-3xl">{e.date.slice(-2)}</b></span></div><span className="min-w-0 p-4"><Tier value={e.tier} /><b className="mt-2 block truncate group-hover:text-[#ed2b3a]">{e.name}</b><small className="mt-2 block truncate text-white/40">{e.city}{e.teams ? ` · ${e.teams} teams` : ''}</small><small className="mt-1 block text-white/25">{e.rankLocked?'Rank locked':`Locks ${new Date(e.rankLockDate).toLocaleDateString('en-US',{month:'short',day:'numeric'})}`}</small></span></button>)}</div></section>
    <section className="mx-auto grid max-w-[1440px] gap-4 px-5 py-8 md:grid-cols-3 lg:px-8"><StatFeature icon={<Gauge />} title="VCR team rating" copy="Compare provisional team ratings based on recorded match results and opponent strength." /><StatFeature icon={<Globe2 />} title="Event strength" copy="Explore upcoming Signature Events and their registered fields." /><StatFeature icon={<BarChart3 />} title="Stat leaders" copy="Compare the best offensive, defensive, autonomous and strategic teams in the world." /></section>
  </>;
}

function EventsView({ loading,error,retry,results, live, openEvent, search, setSearch, filters, setters, extras, setExtras }: any) {
  const update = (key:string, value:string|boolean) => setExtras((old:any) => ({...old,[key]:value}));
  const eventRegionOptions = eventRegionsForCountry(filters.region);
  const changeCountry = (country:string) => { setters.setRegion(country); update('eventRegion','All'); };
  const reset = () => { setSearch(''); setters.setRegion('All'); setters.setEventClass('All'); setters.setFormat('All'); setters.setTime('All events'); setters.setGrade('All'); setExtras({ season: '2026–27: Override', level: 'All', from: '', to: '', eventRegion: 'All', city: '', affiliation: '', registrationOpen: false, spotsOpen: false, worldQualifier: false, girlPowered: false, includeCanceled: false }); };
  return <section className="mx-auto max-w-[1440px] px-5 py-10 lg:px-8"><PageHead eyebrow="Competition calendar" title="Find your next event" copy="Search the worldwide V5RC calendar by location, date, event format, grade and registration availability." />
    <div className="mt-8 border border-white/10 bg-[#101319] p-4"><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4"><div className="md:col-span-2 xl:col-span-4"><FilterInput icon={<Search />} value={search} onChange={setSearch} placeholder="Search events by name or location" /></div><FilterSelect label="Country" allLabel="All countries" value={filters.region} options={vexCountries} onChange={changeCountry} /><FilterSelect label="Event region" allLabel="All event regions" value={extras.eventRegion} options={eventRegionOptions} onChange={(v:string)=>update('eventRegion',v)} /><FilterSelect label="Season" value={extras.season} options={['2026–27: Override','2025–26: Push Back','2024–25: High Stakes','2023–24: Over Under']} onChange={(v:string)=>update('season',v)} /><FilterSelect label="Event type" allLabel="All types" value={filters.eventClass} options={['All','Open Tournament','Invitational Tournament','School-Based Tournament','League','Live Remote Skills']} onChange={setters.setEventClass} /><FilterSelect label="Event format" allLabel="All formats" value={filters.format} options={['All','In-Person','Invitational','Remote','Skills Only']} onChange={setters.setFormat} /><FilterSelect label="Grade level" allLabel="All grade levels" value={filters.grade} options={['All','Middle School','High School']} onChange={setters.setGrade} /><FilterSelect label="Level class" allLabel="All level classes" value={extras.level} options={['All','Event Region Championship','National Championship','World Championship','Signature Event','Spotlight Event','Conference Championship','JROTC Brigade Championship','JROTC National Championship','Showcase Event']} onChange={(v:string)=>update('level',v)} /><FilterSelect label="Time" value={filters.time} options={['All events','Upcoming only','Next 30 days']} onChange={setters.setTime} /><FilterInput value={extras.city} onChange={(v:string)=>update('city',v)} placeholder="City" /><FilterInput value={extras.affiliation} onChange={(v:string)=>update('affiliation',v)} placeholder="Team affiliation" /><label className="filter-date"><span>From date</span><input type="date" value={extras.from} onChange={e=>update('from',e.target.value)} /></label><label className="filter-date"><span>To date</span><input type="date" value={extras.to} onChange={e=>update('to',e.target.value)} /></label></div>
      <div className="mt-4 flex flex-wrap items-center gap-x-5 gap-y-3 border-t border-white/10 pt-4">{[['registrationOpen','Registration open'],['spotsOpen','Spots open'],['worldQualifier','World qualifiers'],['girlPowered','Girl Powered'],['includeCanceled','Include canceled']].map(([key,label]) => <label key={key} className="flex cursor-pointer items-center gap-2 text-xs text-white/60"><input type="checkbox" checked={extras[key]} onChange={e=>update(key,e.target.checked)} className="accent-[#ed2b3a]" />{label}</label>)}<button onClick={reset} className="ml-auto text-xs font-black uppercase tracking-wider text-white/40 hover:text-white">Reset filters</button></div>
    </div>
    <div className="mt-5 flex items-center justify-between"><p className="text-sm text-white/45"><b className="text-white">{results.length}</b> events found {live && <span className="ml-2 text-emerald-400">● Live Event.VEX data</span>}</p><span className="flex items-center gap-2 text-xs text-white/35"><Filter className="h-3.5 w-3.5" /> Ranked by date</span></div>
    {error&&<LoadError message={error} retry={retry} />}{loading&&<p role="status" className="mt-5 text-sm text-white/60">Loading official events…</p>}<div className="mt-3 space-y-3">{results.map((e:any) => <article onClick={()=>openEvent(e)} key={e.id} className="grid cursor-pointer gap-4 border border-white/10 bg-[#101319] p-5 hover:border-white/25 sm:grid-cols-[95px_1fr_auto] sm:items-center"><div className="border-b border-white/10 pb-3 sm:border-b-0 sm:border-r sm:pb-0"><small className="font-black text-[#ed2b3a]">{new Date(`${e.date}T12:00:00`).toLocaleString('en',{month:'short'}).toUpperCase()}</small><b className="block text-4xl">{e.date.slice(-2)}</b><small className="text-white/35">to {e.end}</small></div><div><div className="flex flex-wrap items-center gap-2"><Tier value={e.tier} /><EventStatus value={e.status} /></div><h2 className="mt-2 text-xl font-black">{e.name}</h2><p className="mt-2 flex flex-wrap gap-x-5 gap-y-1 text-xs text-white/40"><span className="flex items-center gap-1"><MapPin className="h-3.5 w-3.5" />{e.city}</span>{e.teams > 0 && <span className="flex items-center gap-1"><Users className="h-3.5 w-3.5" />{e.teams} teams</span>}<span>{e.grade}</span><span>{e.format}</span>{e.sku && <span>{e.sku}</span>}</p></div><button onClick={click=>{click.stopPropagation();openEvent(e)}} aria-label={`View ${e.name} details`} className="grid h-10 w-10 place-items-center border border-white/10 hover:bg-white hover:text-black"><ChevronRight /></button></article>)}{!loading&&!error&&!results.length && <Empty text="No events match those filters. Try widening your search." />}</div>
  </section>;
}

function EventInfoView({ event, goBack, openTeam }: {event:any;goBack:()=>void;openTeam:(team:any)=>void}) {
  const [details,setDetails] = useState<any>(()=>eventDetailCache.get(String(event.id))??null);
  const [loading,setLoading] = useState(()=>!eventDetailCache.has(String(event.id)));
  const [tab,setTab] = useState('general');
  const [detailError,setDetailError]=useState('');
  const [detailRetry,setDetailRetry]=useState(0);
  const [resultsTab,setResultsTab] = useState('qualification');
  const [skillsMode,setSkillsMode] = useState('combined');
  const [qualificationView,setQualificationView]=useState('ranking');
  const [eventTabsRestored,setEventTabsRestored]=useState(false);
  useEffect(()=>{try{const saved=JSON.parse(sessionStorage.getItem(`vexrank-event-tabs-${event.id}`)??'null');if(saved?.tab)setTab(saved.tab);if(saved?.resultsTab)setResultsTab(saved.resultsTab);if(saved?.skillsMode)setSkillsMode(saved.skillsMode);if(saved?.qualificationView)setQualificationView(saved.qualificationView)}catch{}setEventTabsRestored(true)},[event.id]);
  useEffect(()=>{if(eventTabsRestored)sessionStorage.setItem(`vexrank-event-tabs-${event.id}`,JSON.stringify({tab,resultsTab,skillsMode,qualificationView}))},[event.id,eventTabsRestored,tab,resultsTab,skillsMode,qualificationView]);
  useEffect(()=>{
    let active=true;
    setLoading(true);setDetailError('');setDetails(null);
    cachedJson(eventDetailUrl(event.id),eventDetailCache,String(event.id)).then((data:any)=>{if(active)setDetails(data)}).catch(error=>{if(active)setDetailError(error.message)}).finally(()=>{if(active)setLoading(false)});
    return()=>{active=false};
  },[event.id,detailRetry]);
  const info=details?.event;
  const teamsList=details?.teams ?? [];
  const divisions=details?.divisions ?? [];
  const awards=details?.awards ?? [];
  const eventSkills=details?.skills ?? [];
  const organizer=details?.organizer ?? {};
  const location=info?.location;
  const dateStart=info?.start ?? `${event.date}T12:00:00`;
  const dateEnd=info?.end ?? `${event.date}T12:00:00`;
  const fullAddress=location ? [location.venue,location.address_1,location.city,location.region,location.postcode,location.country].filter(Boolean).join(', ') : event.city;
  const officialUrl=info?.officialUrl ?? `https://events.vex.com/robot-competitions/vex-robotics-competition/${event.sku}.html`;
  const mapsUrl=`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(fullAddress)}`;
  const tabs=[['general','General info'],['agenda','Agenda'],['travel','Travel info'],['webcast','Webcast'],['results','Results'],['awards','Awards'],['teams','Teams']];
  const eventDays=Array.from({length:Math.min(10,Math.max(1,Math.floor((new Date(dateEnd).getTime()-new Date(dateStart).getTime())/86400000)+1))},(_,index)=>new Date(new Date(dateStart).getTime()+index*86400000));
  const agendaData=parseAgenda(organizer.agenda,eventDays);
  const generalSummary=simplifyGeneralInfo(organizer.general);
  return <section className="mx-auto max-w-[1440px] px-5 py-10 lg:px-8">
    <button onClick={goBack} className="mb-6 flex items-center gap-2 text-sm font-bold text-white/50 hover:text-white"><ArrowLeft className="h-4 w-4" /> Back to events</button>
    <div className="border border-white/10 bg-[radial-gradient(circle_at_90%_10%,rgba(237,43,58,.18),transparent_30%),#101319] p-6 sm:p-8"><div className="flex flex-wrap items-center gap-2"><Tier value={event.tier} /><EventStatus value={/cancell?ed/i.test(info?.name??event.name??'')?'Cancelled':info?.ongoing?'In progress':info?.end?(new Date(info.end)<new Date()?'Completed':'Upcoming'):(event.status??'Upcoming')} /></div><p className="mt-5 text-xs font-black uppercase tracking-[.18em] text-[#ed2b3a]">{event.sku ?? info?.sku ?? 'Official V5RC event'}</p><h1 className="mt-2 max-w-5xl text-3xl font-black tracking-[-.04em] sm:text-5xl">{info?.name ?? event.name}</h1><a href={officialUrl} target="_blank" rel="noreferrer" className="mt-4 inline-flex items-center gap-2 text-xs font-black uppercase tracking-wider text-white/45 hover:text-white">Open on Event.VEX <ArrowUpRight className="h-4 w-4" /></a><div className="mt-6 flex flex-wrap gap-x-8 gap-y-3 text-sm text-white/55"><span className="flex items-center gap-2"><CalendarDays className="h-4 w-4 text-[#ed2b3a]" />{new Date(dateStart).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})} – {new Date(dateEnd).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}</span><span className="flex items-center gap-2"><MapPin className="h-4 w-4 text-[#ed2b3a]" />{fullAddress}</span></div></div>
    <div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Metric label="Program" value={info?.program?.code ?? 'V5RC'} detail={info?.program?.name ?? 'VEX V5 Robotics Competition'} /><Metric label="Season" value={seasonYearLabel(info?.season?.name ?? event.season)} detail={info?.season?.name ?? event.season ?? 'Official season'} /><Metric label="Level class" value={event.levelClass ?? event.class ?? 'Other'} detail={event.eventType ?? 'Official competition'} /><Metric label="Registered teams" value={loading ? '…' : String(teamsList.length)} detail={loading ? 'Loading Event.VEX registrations' : 'Live registration list'} /></div>
    <nav className="mt-4 flex overflow-x-auto border border-white/10 bg-[#101319]" aria-label="Event information">{tabs.map(([key,label])=><button key={key} onClick={()=>setTab(key)} className={`whitespace-nowrap border-r border-white/10 px-5 py-4 text-xs font-black uppercase tracking-wider transition ${tab===key?'bg-[#ed2b3a] text-white':'text-white/45 hover:bg-white/[.04] hover:text-white'}`}>{label}{key==='awards'&&awards.length>0?` ${awards.length}`:''}</button>)}</nav>
    <div className="mt-4">
      {detailError&&<LoadError message={detailError} retry={()=>{eventDetailCache.delete(String(event.id));setDetailRetry(value=>value+1)}} />}
      {loading&&<article className="border border-white/10 bg-[#101319] p-8 text-sm text-white/40">Loading official event information…</article>}
      {!loading&&!detailError&&tab==='general'&&<div className="grid gap-4 lg:grid-cols-[1fr_1.4fr]"><article className="border border-white/10 bg-[#101319] p-6"><SectionTitle eyebrow="Event profile" title="Essential details" icon={<CircleDot />} /><dl className="mt-4 text-sm">{[['Event code',event.sku ?? info?.sku],['Format',event.format],['Grade level',event.grade],['Event region',event.eventRegion ?? location?.region],['Venue',location?.venue],['Divisions',info?.divisions?.map((division:any)=>division.name).join(', ') || 'To be announced']].map(([label,value])=><div key={label as string} className="flex justify-between gap-6 border-b border-white/[.07] py-4"><dt className="text-white/40">{label}</dt><dd className="text-right font-bold">{value || 'Not listed'}</dd></div>)}</dl></article><article className="border border-white/10 bg-[#101319] p-6"><SectionTitle eyebrow="From the organizer" title="What you need to know" icon={<Globe2 />} />{generalSummary?<p className="mt-5 whitespace-pre-line text-sm leading-7 text-white/60">{generalSummary}</p>:<p className="mt-5 text-sm text-white/45">No additional organizer notes have been published yet.</p>}</article></div>}
      {!loading&&!detailError&&tab==='agenda'&&<article className="border border-white/10 bg-[#101319] p-6"><SectionTitle eyebrow="Event schedule" title="Agenda" icon={<CalendarDays />} />{agendaData.notes.length>0&&<div className="mt-5 border-l-2 border-[#ed2b3a] bg-white/[.025] px-4 py-3 text-xs leading-5 text-white/45">{agendaData.notes.join(' ')}</div>}<div className="mt-5 grid items-start gap-3 lg:grid-cols-3">{agendaData.days.map((day:any,index:number)=><section key={`${day.title}-${index}`} className="border border-white/10 p-5"><p className="text-xs font-black uppercase tracking-wider text-[#ed2b3a]">Day {index+1}</p><h3 className="mt-2 text-xl font-black">{day.title}</h3>{day.entries.length?<div className="mt-4 divide-y divide-white/[.06]">{day.entries.map((entry:any,entryIndex:number)=><div key={`${entry.time}-${entryIndex}`} className="grid gap-1 py-3 text-sm sm:grid-cols-[minmax(0,1fr)_auto] sm:gap-3"><span className="font-semibold leading-5 text-white/65">{entry.activity}{entry.location&&<small className="block text-[10px] font-normal text-white/30">{entry.location}</small>}</span>{entry.time&&<time className="whitespace-nowrap text-right font-black text-white/75">{entry.time}</time>}</div>)}</div>:<p className="mt-4 text-sm text-white/40">Detailed times have not been published for this day.</p>}</section>)}</div>{!organizer.agenda&&<OfficialFallback href={officialUrl} text="Check the Event.VEX agenda" />}</article>}
      {!loading&&!detailError&&tab==='travel'&&<article className="border border-white/10 bg-[#101319] p-6"><SectionTitle eyebrow="Plan your visit" title="Travel information" icon={<MapPin />} /><div className="mt-5 grid gap-4 md:grid-cols-2"><div className="border border-white/10 p-5"><p className="text-xs font-black uppercase tracking-wider text-white/35">Venue</p><h3 className="mt-2 text-xl font-black">{location?.venue || 'Venue not announced'}</h3><p className="mt-2 text-sm leading-6 text-white/50">{fullAddress}</p><a href={mapsUrl} target="_blank" rel="noreferrer" className="mt-5 inline-flex items-center gap-2 border border-white/15 px-4 py-3 text-xs font-black uppercase tracking-wider hover:bg-white hover:text-black">Open in maps <ArrowUpRight className="h-4 w-4" /></a></div><div className="border border-white/10 p-5"><p className="text-xs font-black uppercase tracking-wider text-white/35">Organizer travel notes</p><h3 className="mt-2 text-xl font-black">Hotels, parking and arrival</h3>{organizer.travel?<p className="mt-3 whitespace-pre-line text-sm leading-7 text-white/60">{organizer.travel}</p>:<><p className="mt-2 text-sm leading-6 text-white/50">No organizer travel notes have been published yet.</p><OfficialFallback href={officialUrl} text="Check Event.VEX travel details" compact /></>}</div></div></article>}
      {!loading&&!detailError&&tab==='webcast'&&<article className="border border-white/10 bg-[#101319] p-6"><SectionTitle eyebrow="Watch live" title="Event webcast" icon={<Globe2 />} /><div className="mt-5 border border-white/10 p-6"><h3 className="text-xl font-black">Webcast information</h3>{organizer.webcast?<p className="mt-3 whitespace-pre-line text-sm leading-7 text-white/60">{organizer.webcast}</p>:<p className="mt-2 max-w-2xl text-sm leading-6 text-white/50">No webcast information has been published yet.</p>}<OfficialFallback href={officialUrl} text="Open webcast section on Event.VEX" /></div></article>}
      {!loading&&!detailError&&tab==='results'&&<EventResults divisions={divisions} skills={eventSkills} resultsTab={resultsTab} setResultsTab={setResultsTab} skillsMode={skillsMode} setSkillsMode={setSkillsMode} qualificationView={qualificationView} setQualificationView={setQualificationView} />}
      {!loading&&!detailError&&tab==='awards'&&<article className="border border-white/10 bg-[#101319] p-6"><SectionTitle eyebrow="Official honors" title="Awards" icon={<Trophy />} />{awards.length?<div className="mt-5 grid gap-3 md:grid-cols-2">{awards.map((award:any)=><div key={award.id} className="border border-white/10 p-5"><p className="text-xs font-black uppercase tracking-wider text-[#ed2b3a]">{award.designation || award.classification || 'Award'}</p><h3 className="mt-2 text-lg font-black">{award.title}</h3>{award.teamWinners?.map((winner:any)=><p key={winner.team?.id ?? winner.team?.name} className="mt-2 text-sm text-white/55"><b className="text-white">{winner.team?.name || winner.team?.number}</b>{winner.team?.team_name?` · ${winner.team.team_name}`:''}</p>)}{award.individualWinners?.map((winner:any,index:number)=><p key={index} className="mt-2 text-sm text-white/55">{winner.name}{winner.team?.name?` · ${winner.team.name}`:''}</p>)}</div>)}</div>:<Empty text="Awards have not been published for this event yet." />}</article>}
      {!loading&&!detailError&&tab==='teams'&&<article className="overflow-hidden border border-white/10 bg-[#101319]"><SectionTitle eyebrow="Live registration" title="Teams attending" icon={<Users />} />{teamsList.length ? <div className="max-h-[650px] overflow-auto"><Table><TableHeader><TableRow className="border-white/10 hover:bg-transparent"><TableHead className="px-5">Team</TableHead><TableHead>Organization</TableHead><TableHead>Grade</TableHead><TableHead className="px-5 text-right">Location</TableHead></TableRow></TableHeader><TableBody>{teamsList.map((team:any)=><TableRow key={team.id} tabIndex={0} role="link" onKeyDown={e=>{if(e.key==='Enter')openTeam({...team,seasonId:info?.season?.id,season:info?.season?.name})}} onClick={()=>openTeam({...team,region:[team.location?.region,team.location?.country].filter(Boolean).join(', '),country:team.location?.country,seasonId:info?.season?.id,season:info?.season?.name??event.season})} className="cursor-pointer border-white/[.07] hover:bg-white/[.04]"><TableCell className="px-5"><b>{team.number}</b><small className="ml-2 text-white/35">{team.name}</small></TableCell><TableCell className="text-white/55">{team.organization || '—'}</TableCell><TableCell className="text-white/55">{team.grade || '—'}</TableCell><TableCell className="px-5 text-right text-white/45">{[team.location?.city,team.location?.region,team.location?.country].filter(Boolean).join(', ')}</TableCell></TableRow>)}</TableBody></Table></div> : <Empty text="No registered teams are listed yet." />}</article>}
    </div>
  </section>;
}

function OfficialFallback({href,text,compact=false}:{href:string;text:string;compact?:boolean}) {
  return <a href={href} target="_blank" rel="noreferrer" className={`${compact?'mt-4':'mt-6'} inline-flex items-center gap-2 border border-white/15 px-4 py-3 text-xs font-black uppercase tracking-wider hover:bg-white hover:text-black`}>{text}<ArrowUpRight className="h-4 w-4" /></a>;
}

function EventResults({divisions,skills,resultsTab,setResultsTab,skillsMode,setSkillsMode,qualificationView,setQualificationView}:any) {
  const [eliminationView,setEliminationView]=useState<'classic'|'bracket'>('classic');
  const [divisionIndex,setDivisionIndex]=useState(0);
  const activeDivisionIndex=Math.min(divisionIndex,Math.max(0,divisions.length-1));
  const visibleDivisions=divisions.length?[divisions[activeDivisionIndex]]:[];
  const skillTeams=Array.from(skills.reduce((map:Map<string,any>,run:any)=>{const key=String(run.team?.id ?? run.team?.name);const row=map.get(key)??{team:run.team,driver:0,auto:0};const type=String(run.type).toLowerCase();if(type.includes('driver'))row.driver=Math.max(row.driver,run.score??0);else row.auto=Math.max(row.auto,run.score??0);map.set(key,row);return map},new Map()).values()).map((row:any)=>({...row,combined:row.driver+row.auto})).sort((a:any,b:any)=>b[skillsMode]-a[skillsMode]);
  const resultTabs=[['qualification','Qualification'],['elimination','Elimination'],['skills','Skills ranking']];
  return <article className="border border-white/10 bg-[#101319] p-6"><SectionTitle eyebrow="Official competition data" title="Results" icon={<BarChart3 />} />
    <div className="mt-5 flex flex-wrap border border-white/10">{resultTabs.map(([key,label])=><button key={key} onClick={()=>setResultsTab(key)} className={`border-r border-white/10 px-5 py-3 text-xs font-black uppercase tracking-wider ${resultsTab===key?'bg-white text-black':'text-white/45 hover:text-white'}`}>{label}</button>)}</div>
    {resultsTab!=='skills'&&divisions.length>1&&<div className="mt-4 flex flex-wrap items-center border border-white/10 bg-black/15"><span className="px-4 py-3 text-[11px] font-black uppercase tracking-[.16em] text-white/35">Division</span>{divisions.map((division:any,index:number)=><button key={division.id??index} onClick={()=>setDivisionIndex(index)} className={`border-l border-white/10 px-5 py-3 text-xs font-black uppercase tracking-wider ${activeDivisionIndex===index?'bg-[#ed2b3a] text-white':'text-white/50 hover:bg-white/[.04] hover:text-white'}`}>{division.name||`Division ${index+1}`}</button>)}</div>}
    {resultsTab==='qualification'&&<div className="mt-5"><div className="mb-4 flex gap-2">{[['ranking','Rankings'],['matches','Match results']].map(([key,label])=><button key={key} onClick={()=>setQualificationView(key)} className={`border px-4 py-2 text-xs font-black uppercase tracking-wider ${qualificationView===key?'border-[#ed2b3a] bg-[#ed2b3a] text-white':'border-white/10 text-white/45 hover:text-white'}`}>{label}</button>)}</div><div className="space-y-8">{visibleDivisions.some((division:any)=>division.rankings.length||qualificationMatches(division).length)?visibleDivisions.map((division:any)=><section key={division.id}><h3 className="mb-3 text-lg font-black">{division.name || 'Division'}</h3>{qualificationView==='ranking'?(division.rankings.length>0?<div className="overflow-x-auto border border-white/10"><Table><TableHeader><TableRow className="border-white/10"><TableHead className="px-4">Rank</TableHead><TableHead>Team</TableHead><TableHead>Record</TableHead><TableHead className="text-right">WP / AP / SP</TableHead></TableRow></TableHeader><TableBody>{division.rankings.slice().sort((a:any,b:any)=>Number(a.rank)-Number(b.rank)).map((row:any)=><TableRow key={row.team?.id} className="border-white/[.07]"><TableCell className="px-4 font-black">#{row.rank}</TableCell><TableCell><b>{row.team?.name || row.team?.number}</b></TableCell><TableCell>{row.wins}–{row.losses}–{row.ties}</TableCell><TableCell className="text-right font-mono text-white/50">{row.wp} / {row.ap} / {row.sp}</TableCell></TableRow>)}</TableBody></Table></div>:<Empty text="Qualification rankings have not been posted yet." />):<MatchGrid matches={qualificationMatches(division)} empty="Qualification match results have not been posted yet." />}</section>):<Empty text="Qualification rankings and matches have not been posted yet." />}</div></div>}
    {resultsTab==='elimination'&&<div className="mt-5"><div className="mb-5 flex gap-2">{([['classic','Classic view'],['bracket','Bracket view']] as const).map(([key,label])=><button key={key} onClick={()=>setEliminationView(key)} className={`border px-4 py-2 text-xs font-black uppercase tracking-wider ${eliminationView===key?'border-[#ed2b3a] bg-[#ed2b3a] text-white':'border-white/10 text-white/45 hover:text-white'}`}>{label}</button>)}</div><div className="space-y-8">{visibleDivisions.some((division:any)=>eliminationMatches(division).length)?visibleDivisions.map((division:any)=><section key={division.id}><h3 className="mb-3 text-lg font-black">{division.name || 'Division'}</h3>{eliminationView==='classic'?<MatchGrid matches={eliminationMatches(division)} empty="Elimination match results have not been posted yet." />:<EliminationBracket division={division} divisionNames={finalistDivisions(division,divisions)} />}</section>):<Empty text="Elimination matches have not been posted yet." />}</div></div>}
    {resultsTab==='skills'&&<div className="mt-5"><div className="mb-4 flex flex-wrap gap-2">{[['driver','Driver skills'],['auto','Auto skills'],['combined','Combined skills']].map(([key,label])=><button key={key} onClick={()=>setSkillsMode(key)} className={`border px-4 py-2 text-xs font-black uppercase tracking-wider ${skillsMode===key?'border-[#ed2b3a] bg-[#ed2b3a] text-white':'border-white/10 text-white/45 hover:text-white'}`}>{label}</button>)}</div>{skillTeams.length?<div className="overflow-x-auto border border-white/10"><Table><TableHeader><TableRow className="border-white/10"><TableHead className="w-20 px-4">Rank</TableHead><TableHead>Team</TableHead><TableHead className="text-right">Driver</TableHead><TableHead className="text-right">Auto</TableHead><TableHead className="px-4 text-right">Combined</TableHead></TableRow></TableHeader><TableBody>{skillTeams.map((row:any,index:number)=><TableRow key={row.team?.id ?? index} className="border-white/[.07]"><TableCell className="px-4 font-black">#{index+1}</TableCell><TableCell><b>{row.team?.name || row.team?.number}</b></TableCell><TableCell className="text-right font-mono">{row.driver}</TableCell><TableCell className="text-right font-mono">{row.auto}</TableCell><TableCell className="px-4 text-right font-mono font-black">{row.combined}</TableCell></TableRow>)}</TableBody></Table></div>:<Empty text="Skills scores have not been posted yet." />}</div>}
  </article>;
}

function qualificationMatches(division:any) { return (division.matches??[]).filter((match:any)=>Number(match.round)===2||/qual/i.test(match.name??'')).sort((a:any,b:any)=>Number(a.matchnum)-Number(b.matchnum)); }
function eliminationMatches(division:any) { const order=(round:number)=>round===6?0:round;return (division.matches??[]).filter((match:any)=>Number(match.round)>=3&&!/qual|practice/i.test(match.name??'')).sort((a:any,b:any)=>order(Number(a.round))-order(Number(b.round))||Number(a.matchnum)-Number(b.matchnum)); }
function MatchGrid({matches,empty='No scored matches in this section yet.'}:{matches:any[];empty?:string}) { return matches.length?<div className="mt-4 grid gap-2 md:grid-cols-2">{matches.map((match:any)=>{const hasScore=(match.alliances??[]).some((alliance:any)=>alliance.score!==null&&alliance.score!==undefined&&Number(alliance.score)>=0);return <div key={match.id} className="border border-white/10 p-4"><div className="mb-3 flex items-center justify-between"><div><b>{match.name}</b><small className="mt-1 block text-white/35">{match.field || (hasScore?'Final score':'Scheduled')}</small></div><span className="text-[10px] font-black uppercase tracking-wider text-white/30">{hasScore?'Final':'Not played'}</span></div><div className="grid grid-cols-2 gap-2">{[...(match.alliances??[])].sort((a:any,b:any)=>(a.color==='red'?0:1)-(b.color==='red'?0:1)).map((alliance:any)=><div key={alliance.color} className={`border-l-2 pl-3 ${alliance.color==='red'?'border-red-400':'border-blue-400'}`}><div className={`font-mono text-lg font-black ${alliance.color==='red'?'text-red-400':'text-blue-400'}`}>{hasScore&&alliance.score!=null?alliance.score:'—'}</div><small className="block truncate text-white/45">{allianceTeams(alliance)}</small></div>)}</div></div>})}</div>:<p className="mt-3 text-sm text-white/35">{empty}</p>; }
function allianceTeams(alliance:any) { const names=(alliance.teams??[]).map((entry:any)=>entry.team?.name??entry.team?.number??entry.name??entry.number).filter(Boolean);return names.length?names.join(' + '):'Teams not assigned'; }

function EliminationBracket({division,divisionNames=[]}:{division:any;divisionNames?:string[]}) {
  const matches=eliminationMatches(division);const seeds=new Map<number,number>();
  const roundInfo=[[6,'Round of 16'],[3,'Quarterfinals'],[4,'Semifinals']] as const;
  const rounds=roundInfo.map(([round,label])=>({round,label,matches:bracketRound(matches,round,round===6?8:round===3?4:2)})).filter(group=>group.matches.some(Boolean));
  const halves=(side:'upper'|'lower')=>rounds.map(group=>{const midpoint=Math.ceil(group.matches.length/2);return{...group,matches:side==='upper'?group.matches.slice(0,midpoint):group.matches.slice(midpoint)}}).filter(group=>group.matches.length);
  const finals=matches.filter((match:any)=>Number(match.round)===5).sort((a:any,b:any)=>Number(a.matchnum)-Number(b.matchnum));
  if(!rounds.length&&finals.length)return <div className="overflow-x-auto border border-white/10 bg-black/15 px-6 py-10"><div className="mx-auto grid w-full min-w-[34rem] max-w-3xl grid-cols-[minmax(12rem,1fr)_minmax(22rem,1.7fr)] items-end"><div className="border border-r-0 border-white/10 bg-[#0d1016]"><div className="flex h-[45px] items-center justify-end border-b border-white/10 px-4 text-[11px] font-black uppercase tracking-[.16em] text-white/40">Divisions</div>{[0,1].map(index=><div key={index} className={`flex min-h-11 items-center justify-end border-r-[3px] px-4 text-right text-xs font-black ${index===0?'border-r-red-500':'border-r-blue-500'} ${index===0?'border-b border-white/10':''}`}>{divisionNames[index]||'Division not listed'}</div>)}</div><FinalSeries matches={finals} seeds={seeds} /></div></div>;
  const BracketHalf=({side,title}:{side:'upper'|'lower';title:string})=><section className="bracket-half"><p className="bracket-half-title text-xs font-black uppercase tracking-[.16em] text-white/45">{title}</p><div className="bracket-rounds">{halves(side).map(group=><div key={group.round} className="bracket-round"><p className="bracket-round-label text-xs font-bold text-white/35">{group.label}</p><div className="bracket-round-matches">{group.matches.map((match:any,index:number)=><div key={match?.id??index} className="bracket-match-slot">{index%2===0&&index+1<group.matches.length?<span className="bracket-join" aria-hidden="true" />:null}{match&&<BracketMatch match={match} seeds={seeds} />}</div>)}</div></div>)}</div></section>;
  return <div className="overflow-x-auto border border-white/10 bg-black/15 p-5"><div className="bracket-layout" style={{'--bracket-height':`${Math.max(28,...rounds.map(group=>Math.ceil(group.matches.length/2)*7))}rem`} as React.CSSProperties}><div className="bracket-halves"><BracketHalf side="upper" title="Upper bracket" /><BracketHalf side="lower" title="Lower bracket" /></div><div className="bracket-final-stage"><div className="bracket-final-card"><p className="mb-3 text-xs font-black uppercase tracking-[.16em] text-[#ed2b3a]">Grand final</p><FinalSeries matches={finals} seeds={seeds} /></div></div></div></div>;
}

function allianceKey(alliance:any){return (alliance?.teams??[]).map((entry:any)=>entry.team?.id??entry.team?.name??entry.name).filter(Boolean).sort().join('|')}
function allianceSeed(alliance:any,seeds:Map<any,any>){const values=(alliance?.teams??[]).map((entry:any)=>seeds.get(Number(entry.team?.id))).filter(Number.isFinite);return values.length?Math.min(...values):null}
function hasAllianceScore(alliance:any){return alliance?.score!==null&&alliance?.score!==undefined&&Number(alliance.score)>=0}

function BracketMatch({match,seeds}:{match:any;seeds:Map<any,any>}) {
  const alliances=[...(match.alliances??[])].sort((a:any,b:any)=>(a.color==='red'?0:1)-(b.color==='red'?0:1));const scored=alliances.length===2&&alliances.every(hasAllianceScore);const winningAlliance=scored&&Number(alliances[0].score)!==Number(alliances[1].score)?(Number(alliances[0].score)>Number(alliances[1].score)?alliances[0]:alliances[1]):null;
  const detail=match.games?.length>1?match.games.map((game:any)=>`${game.name}: Red ${game.alliances?.find((a:any)=>a.color==='red')?.score??'—'} – Blue ${game.alliances?.find((a:any)=>a.color==='blue')?.score??'—'}`).join(' · '):scored?`${match.name}: Red ${alliances.find((alliance:any)=>alliance.color==='red')?.score ?? '—'} – Blue ${alliances.find((alliance:any)=>alliance.color==='blue')?.score ?? '—'}`:`${match.name}: not scored yet`;
  return <div tabIndex={0} title={detail} className="bracket-card group relative w-full border border-white/10 bg-[#151a22] shadow-lg outline-none focus:border-white/30"><div className="absolute left-full top-1/2 z-20 ml-2 hidden w-max max-w-64 -translate-y-1/2 border border-white/15 bg-[#080a0e] px-3 py-2 text-xs text-white/75 shadow-xl group-hover:block group-focus:block">{detail}</div>{alliances.map((alliance:any,index:number)=>{const won=winningAlliance===alliance;const lost=Boolean(winningAlliance)&&!won;const isRed=alliance.color==='red';return <div key={alliance.color??index} className={`flex min-h-10 items-center gap-2 border-l-[3px] px-3 py-2 ${index?'border-t border-t-white/[.07]':''} ${isRed?'border-l-red-500':'border-l-blue-500'} ${won?'bg-emerald-400/[.10] text-white ring-1 ring-inset ring-emerald-400/30':lost?'bg-black/25 opacity-35':'text-white/65'}`}><span aria-label={`${isRed?'Red':'Blue'} alliance`} className={`flex h-4 w-4 shrink-0 items-center justify-center text-[8px] font-black text-white ${isRed?'bg-red-500':'bg-blue-500'}`}>{isRed?'R':'B'}</span><span className="w-7 shrink-0 text-[11px] font-black text-white/40">{allianceSeed(alliance,seeds)?`#${allianceSeed(alliance,seeds)}`:'—'}</span><span className="max-w-32 flex-1 truncate text-xs font-bold">{allianceTeams(alliance)}</span><span className="font-mono text-sm font-black">{hasAllianceScore(alliance)?alliance.score:'—'}</span></div>})}</div>;
}

function FinalSeries({matches,seeds}:{matches:any[];seeds:Map<any,any>}) {
  if(!matches.length)return <div className="border border-dashed border-white/15 p-5 text-sm text-white/35">Final not posted yet.</div>;
  const first=matches.find((match:any)=>(match.alliances??[]).length===2)??matches[0];const finalists=[...(first.alliances??[])].sort((a:any,b:any)=>(a.color==='red'?0:1)-(b.color==='red'?0:1));const keys=finalists.map(allianceKey);const wins=[0,0];
  for(const match of matches){const alliances=match.alliances??[];if(alliances.length!==2||!alliances.every(hasAllianceScore)||Number(alliances[0].score)===Number(alliances[1].score))continue;const winningAlliance=Number(alliances[0].score)>Number(alliances[1].score)?alliances[0]:alliances[1];const index=keys.indexOf(allianceKey(winningAlliance));if(index>=0)wins[index]++}
  const winner=Math.max(...wins)<2||wins[0]===wins[1]?-1:(wins[0]>wins[1]?0:1);const detail=matches.map((match:any,index:number)=>{const alliances=match.alliances??[];return `Game ${index+1}: ${alliances.length===2&&alliances.every(hasAllianceScore)?`Red ${alliances.find((a:any)=>a.color==='red')?.score??'—'} – Blue ${alliances.find((a:any)=>a.color==='blue')?.score??'—'}`:'not scored'}`}).join(' · ');
  return <div tabIndex={0} title={detail} className="group relative border border-white/10 bg-[#151a22] shadow-xl outline-none focus:border-white/30"><div className="absolute bottom-full right-0 z-20 mb-2 hidden w-max max-w-80 border border-white/15 bg-[#080a0e] px-3 py-2 text-xs leading-5 text-white/75 shadow-xl group-hover:block group-focus:block">{detail}</div><div className="border-b border-white/10 px-3 py-2 text-center font-mono text-lg font-black text-[#ed2b3a]">{wins[0]} : {wins[1]}</div>{finalists.map((alliance:any,index:number)=>{const won=winner===index;const lost=winner>=0&&!won;const isRed=alliance.color==='red';return <div key={keys[index]||index} className={`flex min-h-11 items-center gap-2 border-l-[3px] px-3 py-2 ${index?'border-t border-t-white/[.07]':''} ${isRed?'border-l-red-500':'border-l-blue-500'} ${won?'bg-emerald-400/[.10] text-white ring-1 ring-inset ring-emerald-400/30':lost?'bg-black/25 opacity-35':'text-white/65'}`}><span aria-label={`${isRed?'Red':'Blue'} alliance`} className={`flex h-4 w-4 shrink-0 items-center justify-center text-[8px] font-black text-white ${isRed?'bg-red-500':'bg-blue-500'}`}>{isRed?'R':'B'}</span><span className="w-7 shrink-0 text-[11px] font-black text-white/40">{allianceSeed(alliance,seeds)?`#${allianceSeed(alliance,seeds)}`:'—'}</span><span className="flex-1 truncate text-xs font-bold">{allianceTeams(alliance)}</span><span className="font-mono font-black">{wins[index]}</span></div>})}</div>;
}


function simplifyGeneralInfo(text:string) {
  const blocks=String(text||'').split(/\n{2,}/).map(block=>block.replace(/\s+/g,' ').trim()).filter(block=>block.length>45&&!/^(grade level|skills challenge|judging format|event dates)/i.test(block));
  const summary=blocks.slice(0,2).join('\n\n');
  return summary.length>900?`${summary.slice(0,897).trim()}…`:summary;
}

function RankingsView({ teams: rows, meta, openTeam, savedState, setSavedState }: { teams: any[]; meta:any; openTeam:(t:any)=>void;savedState:any;setSavedState:(state:any)=>void }) {
  const [season,setSeason]=useState(savedState.season??'2026–27 Override');const [rankingCountry,setRankingCountry]=useState(savedState.country??'All');const [rankingRegion,setRankingRegion]=useState(savedState.region??'All');const [gradeList,setGradeList]=useState(savedState.grade??'All teams');const [rankingSearch,setRankingSearch]=useState(savedState.search??'');const [archives,setArchives]=useState<Record<string,any>>({});const [archiveError,setArchiveError]=useState('');const [archiveRetry,setArchiveRetry]=useState(0);const [visibleCount,setVisibleCount]=useState(savedState.visibleCount??100);
  useEffect(()=>{if(season==='2026–27 Override'||archives[season])return;let active=true;setArchiveError('');const base='/rankings-2025-26.json?v=6';fetch(base).then(response=>response.ok?response.json():Promise.reject()).then((data:any)=>{if(active&&Array.isArray(data.rankings))setArchives(old=>({...old,[season]:data}))}).catch(()=>{if(active)setArchiveError('The season archive could not be loaded. Please retry.');});return()=>{active=false}},[season,archives,archiveRetry]);
  useEffect(()=>setVisibleCount(100),[season,rankingCountry,rankingRegion,gradeList,rankingSearch]);
  useEffect(()=>setSavedState({season,country:rankingCountry,region:rankingRegion,grade:gradeList,search:rankingSearch,visibleCount}),[season,rankingCountry,rankingRegion,gradeList,rankingSearch,visibleCount,setSavedState]);
  const historical=archives[season];const activeRows=season==='2026–27 Override'?rows:(historical?.rankings??[]);const activeMeta=season==='2026–27 Override'?meta:historical;const countries=['All',...Array.from(new Set(activeRows.map((team:any)=>team.country).filter(Boolean))).sort()] as string[];const regionOf=(team:any)=>team.eventRegion??String(team.region??'Unassigned').split(',')[0].trim();const regions=['All',...Array.from(new Set(activeRows.filter((team:any)=>rankingCountry==='All'||team.country===rankingCountry).map(regionOf).filter(Boolean))).sort()] as string[];const filteredRows=activeRows.filter((team:any)=>(gradeList==='All teams'||team.grade===gradeList)&&(rankingCountry==='All'||team.country===rankingCountry)&&(rankingRegion==='All'||regionOf(team)===rankingRegion)&&(!rankingSearch||`${team.number} ${team.name}`.toLowerCase().includes(rankingSearch.toLowerCase())));const visibleRows=filteredRows.slice(0,visibleCount);const isFullArchive=season==='2025–26 Push Back';
  return <section className="mx-auto max-w-[1440px] px-5 py-10 lg:px-8"><PageHead eyebrow="Live VEX Competitive Rating" title="World team ranking" copy="Compare the current Override standings with the complete Push Back archive, then narrow by school level, country and event region." />
    {archiveError&&<LoadError message={archiveError} retry={()=>setArchiveRetry(value=>value+1)} />}<div className="mt-8 flex border border-white/10 bg-[#101319]">{['All teams','High School','Middle School'].map(level=><button key={level} onClick={()=>setGradeList(level)} className={`flex-1 px-3 py-4 text-xs font-black uppercase tracking-wider ${gradeList===level?'bg-[#ed2b3a] text-white':'text-white/45 hover:text-white'}`}>{level==='All teams'?level:`${level} ranking`}</button>)}</div>
    <div className="mt-3 grid gap-3 border border-white/10 bg-[#101319] p-4 md:grid-cols-2 xl:grid-cols-4"><FilterSelect label="Season" value={season} options={['2026–27 Override','2025–26 Push Back']} onChange={value=>{setSeason(value);setRankingCountry('All');setRankingRegion('All')}} /><FilterSelect label="Country" allLabel="All countries" value={rankingCountry} options={countries} onChange={value=>{setRankingCountry(value);setRankingRegion('All')}} /><FilterSelect label="Event region" allLabel="All event regions" value={rankingRegion} options={regions} onChange={setRankingRegion} /><FilterInput icon={<Search />} value={rankingSearch} onChange={setRankingSearch} placeholder="Search team number or name" /></div>
    <div className="mt-4 grid gap-3 sm:grid-cols-3"><Metric label={`${gradeList} rated`} value={season!=='2026–27 Override'&&!historical?'…':String(filteredRows.length)} detail={rankingCountry==='All'?'Minimum four official matches':`${filteredRows.length} teams in ${rankingCountry}`} /><Metric label="Events processed" value={String(activeMeta?.eventsProcessed ?? '…')} detail={`${activeMeta?.matchesProcessed ?? '…'} official matches`} /><Metric label="Rating leader" value={String(filteredRows[0]?.rating ?? '…')} detail={filteredRows[0] ? `${filteredRows[0].number} · ${gradeList} #1` : 'No qualifying teams'} /></div>
    <p className="mt-3 text-xs text-white/40">{isFullArchive?'Complete archived season data.':`Live official-data sample${activeMeta?.eventsProcessed?` · ${activeMeta.eventsProcessed} events`:''}. The complete season archive is not available yet.`}</p>
    <div className="mt-6 overflow-hidden border border-white/10 bg-[#101319]"><Table><TableHeader><TableRow className="border-white/10 hover:bg-transparent"><TableHead className="w-20 px-5 text-[10px] font-black uppercase tracking-wider text-white/35">Rank</TableHead><TableHead className="text-[10px] font-black uppercase tracking-wider text-white/35">Team</TableHead><TableHead className="text-[10px] font-black uppercase tracking-wider text-white/35">Region</TableHead><TableHead className="text-[10px] font-black uppercase tracking-wider text-white/35">Record</TableHead><TableHead className="text-[10px] font-black uppercase tracking-wider text-white/35">Matches</TableHead><TableHead className="px-5 text-right text-[10px] font-black uppercase tracking-wider text-white/35">VCR</TableHead></TableRow></TableHeader><TableBody>{visibleRows.map((t:any,index:number) => <TableRow key={t.number} tabIndex={0} role="link" onKeyDown={e=>{if(e.key==='Enter')openTeam({...t,season,seasonId:season==='2025–26 Push Back'?197:204})}} onClick={() => openTeam({...t,season,seasonId:season==='2025–26 Push Back'?197:204})} className="cursor-pointer border-white/[.07] hover:bg-white/[.04]"><TableCell className="px-5"><span className={`text-lg font-black ${index < 3 ? 'text-[#ed2b3a]' : 'text-white/40'}`}>#{index+1}</span></TableCell><TableCell><b>{t.number}</b><small className="ml-3 text-white/35">{t.name}</small></TableCell><TableCell className="text-white/45">{t.region}</TableCell><TableCell className="font-mono text-white/65">{t.record}</TableCell><TableCell className="text-white/45">{t.matches}</TableCell><TableCell className="px-5 text-right font-mono text-lg font-black">{t.rating}<small className="ml-2 text-xs text-white/25">±{t.confidence}</small></TableCell></TableRow>)}</TableBody></Table></div>
    {visibleCount<filteredRows.length&&<button onClick={()=>setVisibleCount((count:number)=>count+250)} className="mt-4 w-full border border-white/10 bg-[#101319] py-3 text-xs font-black uppercase tracking-wider text-white/50 hover:border-white/30 hover:text-white">Show more teams · {filteredRows.length-visibleCount} remaining</button>}
    <p className="mt-4 text-xs text-white/30">Provisional VCR uses the specification’s opponent-adjusted match model and conservative uncertainty adjustment. Contribution, autonomous and finish components will activate as complete breakdown data becomes available.</p>
  </section>;
}

function StatRankingsView({ teams: rows, openTeam }: { teams: any[]; openTeam:(t:any)=>void }) {
  const [category, setCategory] = useState('Offense');
  const [statRegion, setStatRegion] = useState('All');
  const [season,setSeason]=useState('2026–27 Override');
  const [historical,setHistorical]=useState<any>(null);
  const [skills,setSkills]=useState<any[]>([]);
  const [visibleCount,setVisibleCount]=useState(100);
  const skillCategory=category.includes('Skills');
  useEffect(()=>{if(season==='2025–26 Push Back'&&!historical)fetch('/rankings-2025-26.json').then(r=>r.json()).then(setHistorical).catch(()=>undefined)},[season,historical]);
  useEffect(()=>{let active=true;setSkills([]);fetch(`/api/skills?season=${season==='2025–26 Push Back'?'197':'204'}`).then(r=>r.ok?r.json():Promise.reject()).then((data:any)=>{if(active)setSkills(data.rankings??[])}).catch(()=>{if(active)setSkills([])});return()=>{active=false}},[season]);
  useEffect(()=>setVisibleCount(100),[category,statRegion,season]);
  const matchRows=season==='2025–26 Push Back'?(historical?.rankings??[]):rows;
  const winRate=(team:any)=>{const [wins,,ties]=String(team.record??'0–0–0').split('–').map(Number);return team.matches?((wins+(ties||0)*.5)/team.matches)*100:0};
  const pickingScore=(team:any)=>Math.max(0,Math.min(100,.45*winRate(team)+.35*Math.max(0,Math.min(100,(team.rating-1250)/7.5))+.2*Math.max(0,Math.min(100,(team.ccwm+20)*1.25))));
  const consistencyScore=(team:any)=>Math.max(0,Math.min(100,100-Number(team.confidence??100)));
  const categories: Record<string,{label:string; description:string; value:(team:any)=>number; suffix:string; lower?:boolean; qualify:(team:any)=>boolean}> = {
    Offense: { label: 'Offensive rating', description: 'Teams that create the most scoring value, with at least 12 scored matches.', value: team => team.opr, suffix: '', qualify: team=>team.matches>=12 },
    Defense: { label: 'Defensive impact', description: 'Lowest opponent score share among teams with at least 12 scored matches.', value: team => team.dpr, suffix: '', lower: true, qualify: team=>team.matches>=12 },
    'Picking Strategy': { label: 'Strategic reliability', description: 'A 0–100 proxy combining results, opponent-adjusted strength and scoring margin. Requires 36 matches across 4 events.', value: pickingScore, suffix: '', qualify: team=>team.matches>=36&&team.events>=4 },
    Consistency: { label: 'Rating stability', description: 'How firmly the rating is supported by repeat results. Requires 36 matches across 4 events.', value: consistencyScore, suffix: '', qualify: team=>team.matches>=36&&team.events>=4 },
    'Auto Skills': { label: 'Autonomous skills', description: 'Official Event.VEX programming-skills score.', value: team => team.autoSkills, suffix: '', qualify: team=>team.autoSkills>0 },
    'Driver Skills': { label: 'Driver skills', description: 'Official Event.VEX driver-skills score.', value: team => team.driverSkills, suffix: '', qualify: team=>team.driverSkills>0 },
    'Combined Skills': { label: 'Combined skills', description: 'Official Event.VEX autonomous plus driver skills total.', value: team => team.combinedSkills, suffix: '', qualify: team=>team.combinedSkills>0 },
  };
  const active = categories[category];
  const sourceRows:any[]=skillCategory?skills:matchRows;
  const regions=['All',...Array.from(new Set(sourceRows.map((team:any)=>team.country).filter(Boolean))).sort()] as string[];
  const ranking = sourceRows.filter(team => active.qualify(team)&&(statRegion === 'All' || team.country === statRegion)).sort((a,b) => active.lower ? active.value(a)-active.value(b) : active.value(b)-active.value(a));
  const visible=ranking.slice(0,visibleCount);
  return <section className="mx-auto max-w-[1440px] px-5 py-10 lg:px-8"><PageHead eyebrow="Performance leaderboards" title="Who leads every part of the game?" copy="Go beyond the overall world ranking and discover the teams setting the standard in scoring, defense, autonomous play and strategy." />
    <div className="mt-8 flex flex-wrap gap-2">{Object.keys(categories).map(key => <button key={key} onClick={()=>setCategory(key)} className={`border px-4 py-2 text-xs font-black transition ${category === key ? 'border-[#ed2b3a] bg-[#ed2b3a] text-white' : 'border-white/10 bg-[#101319] text-white/50 hover:border-white/30 hover:text-white'}`}>{key}</button>)}</div>
    <div className="mt-5 grid gap-3 border border-white/10 bg-[#101319] p-5 sm:grid-cols-[1fr_1fr_2fr] sm:items-end"><FilterSelect label="Season" value={season} options={['2026–27 Override','2025–26 Push Back']} onChange={value=>{setSeason(value);setStatRegion('All')}} /><FilterSelect label="Region" value={statRegion} options={regions} onChange={setStatRegion} /><div><p className="text-xs font-black uppercase tracking-[.16em] text-[#ed2b3a]">{active.label}</p><p className="mt-1 text-sm text-white/40">{active.description}</p></div></div>
    <div className="mt-4 overflow-hidden border border-white/10 bg-[#101319]"><Table><TableHeader><TableRow className="border-white/10 hover:bg-transparent"><TableHead className="w-20 px-5 text-[10px] font-black uppercase tracking-wider text-white/35">Rank</TableHead><TableHead className="text-[10px] font-black uppercase tracking-wider text-white/35">Team</TableHead><TableHead className="text-[10px] font-black uppercase tracking-wider text-white/35">Region</TableHead><TableHead className="text-[10px] font-black uppercase tracking-wider text-white/35">{skillCategory?'Grade':'Overall'}</TableHead><TableHead className="px-5 text-right text-[10px] font-black uppercase tracking-wider text-white/35">{active.label}</TableHead></TableRow></TableHeader><TableBody>{visible.map((team,index)=><TableRow key={team.number} onClick={()=>!skillCategory&&openTeam({...team,season})} className={`${skillCategory?'':'cursor-pointer'} border-white/[.07] hover:bg-white/[.04]`}><TableCell className="px-5 text-lg font-black text-white/35">#{index+1}</TableCell><TableCell><b>{team.number}</b><small className="ml-3 text-white/35">{team.name}</small></TableCell><TableCell className="text-white/45">{team.region}</TableCell><TableCell className="text-white/45">{skillCategory?(team.grade??'—'):`World #${team.rank}`}</TableCell><TableCell className="px-5 text-right font-mono text-lg font-black">{active.value(team).toFixed(skillCategory||category==='Picking Strategy'||category==='Consistency'?0:1)}{active.suffix}</TableCell></TableRow>)}</TableBody></Table></div>
    {visibleCount<ranking.length&&<button onClick={()=>setVisibleCount(count=>count+250)} className="mt-4 w-full border border-white/10 bg-[#101319] py-3 text-xs font-black uppercase tracking-wider text-white/50 hover:border-white/30 hover:text-white">Show more teams · {ranking.length-visibleCount} remaining</button>}
    {!visible.length&&<div className="mt-4"><Empty text="No teams currently meet this category’s qualification threshold." /></div>}
    <p className="mt-4 text-xs text-white/30">Skills scores come directly from the official Event.VEX world skills standings. Strategic reliability and rating stability require 36 scored matches across at least four events, preventing small samples from leading those categories.</p>
  </section>;
}

function TeamsView({ results, search, setSearch, region, setRegion, range, setRange, openTeam }: any) {
  const [archive,setArchive]=useState<any>(null);const [archiveLoading,setArchiveLoading]=useState(false);const [archiveError,setArchiveError]=useState('');
  useEffect(()=>{const number=search.trim().toUpperCase();if(!/^[0-9]+[A-Z0-9-]+$/.test(number)){setArchive(null);setArchiveError('');return}const timer=setTimeout(()=>{setArchiveLoading(true);setArchiveError('');cachedJson(`/api/teams/${encodeURIComponent(number)}?profile=v7`,teamHistoryCache,number).then(setArchive).catch(error=>{setArchive(null);setArchiveError(error.message)}).finally(()=>setArchiveLoading(false))},200);return()=>clearTimeout(timer)},[search]);
  return <section className="mx-auto max-w-[1440px] px-5 py-10 lg:px-8"><PageHead eyebrow="Team directory" title="Find any V5RC team" copy="Search by team number or name, then open a complete competitive profile." />
    <div className="mt-8 grid gap-3 border border-white/10 bg-[#101319] p-4 md:grid-cols-[2fr_1fr_1fr]"><label className="relative"><Search className="absolute left-3 top-3 h-4 w-4 text-white/35" /><input autoFocus value={search} onChange={e => setSearch(e.target.value)} placeholder="Try 2775V or Quantum Robotics" className="h-10 w-full border border-white/10 bg-black/20 pl-9 pr-3 text-sm outline-none focus:border-white/30" /></label><NativeSelect value={region} onChange={e => setRegion(e.target.value)} className="w-full [&_select]:h-10 [&_select]:rounded-none [&_select]:border-white/10 [&_select]:bg-black/20"><NativeSelectOption>All</NativeSelectOption>{['USA','Canada','Singapore','Australia','Hong Kong'].map(x => <NativeSelectOption key={x}>{x}</NativeSelectOption>)}</NativeSelect><NativeSelect value={range} onChange={e => setRange(e.target.value)} className="w-full [&_select]:h-10 [&_select]:rounded-none [&_select]:border-white/10 [&_select]:bg-black/20"><NativeSelectOption>All</NativeSelectOption><NativeSelectOption>Top 5</NativeSelectOption><NativeSelectOption>Top 10</NativeSelectOption><NativeSelectOption>11–50</NativeSelectOption></NativeSelect></div>
    {archiveLoading&&<p className="mt-4 text-sm text-white/40">Searching the complete Event.VEX team archive…</p>}
    {archive&&<button onClick={()=>openTeam({...archive.team,history:archive})} className="mt-4 flex w-full items-center gap-4 border border-[#ed2b3a]/40 bg-[#ed2b3a]/[.07] p-5 text-left hover:border-[#ed2b3a]"><span className="grid h-12 w-12 place-items-center bg-[#ed2b3a] font-black">{archive.team.number.slice(-1)}</span><span><b className="block text-lg">{archive.team.number} · {archive.team.name}</b><small className="text-white/45">{archive.team.active?'Active this season':'Inactive this season'} · {archive.team.seasons} seasons · {archive.events.length} events · {archive.awards.length} awards</small></span><ArrowRight className="ml-auto" /></button>}
    {archiveError&&<p className="mt-4 text-sm text-rose-300">{archiveError}</p>}
    <div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{results.map((t:any) => <button key={t.number} onClick={() => openTeam(t)} className="group border border-white/10 bg-[#101319] p-5 text-left hover:-translate-y-0.5 hover:border-white/25"><div className="flex items-start justify-between"><span className="grid h-12 w-12 place-items-center bg-white/[.04] font-black text-white/35">#{t.rank}</span><span className="font-mono text-lg font-black">{t.rating}</span></div><h2 className="mt-5 text-xl font-black group-hover:text-[#ed2b3a]">{t.number}</h2><p className="text-sm text-white/65">{t.name}</p><p className="mt-3 text-xs text-white/35">{t.region}</p><div className="mt-5 grid grid-cols-3 border-t border-white/10 pt-4 text-xs"><span><small className="block text-white/30">Record</small><b className="mt-1 block font-mono">{t.record}</b></span><span><small className="block text-white/30">Events</small><b className="mt-1 block">{t.events}</b></span><span><small className="block text-white/30">Movement</small><b className="mt-1 block"><Trend value={t.change} /></b></span></div></button>)}{!results.length&&!archive&&!archiveLoading && <div className="md:col-span-2 xl:col-span-3"><Empty text="No current-season ranking matches. Enter the complete team number to search the historical archive." /></div>}</div>
  </section>;
}

function SeasonRatingChart({data,onOpenEvent}:{data:any[];onOpenEvent:(point:any)=>void}) {
  const [selected,setSelected]=useState<any>(data.at(-1));
  useEffect(()=>setSelected(data.at(-1)),[data]);
  if(!data.length)return <article className="mt-6 border border-white/10 bg-[#101319]"><SectionTitle eyebrow="Season progression" title="Tournament rating movement" icon={<BarChart3 />} /><Empty text="No scored tournament matches are available for this season." /></article>;
  const chartData=data.map((point,index)=>({...point,index,label:new Date(point.eventDate).toLocaleDateString(undefined,{month:'short',day:'numeric'})}));
  const ratings=chartData.map(point=>point.rating);const low=Math.min(...ratings);const high=Math.max(...ratings);const padding=Math.max(15,Math.ceil((high-low)*.15));
  const detail=selected??chartData.at(-1);
  return <article className="mt-6 border border-white/10 bg-[#101319]">
    <SectionTitle eyebrow="Season progression" title="Tournament rating movement" icon={<BarChart3 />} />
    <div className="p-5">
      <div className="mb-5 flex flex-col gap-2 border-l-2 border-[#ed2b3a] bg-white/[.025] p-4 sm:flex-row sm:items-center">
        <div className="min-w-0">
          <p className="text-xs font-black uppercase tracking-wider text-white/35">{new Date(detail.eventDate).toLocaleDateString(undefined,{year:'numeric',month:'long',day:'numeric'})}</p>
          <button onClick={()=>onOpenEvent(detail)} className="mt-1 block max-w-full truncate text-left font-black hover:text-[#ed2b3a]">{detail.event}</button>
        </div>
        <div className="sm:ml-auto sm:text-right">
          <b className={`font-mono text-xl ${detail.change>=0?'text-emerald-400':'text-rose-400'}`}>{detail.change>=0?'+':''}{detail.change} pts</b>
          <p className="text-xs text-white/35">Rating {detail.rating} · {detail.matches} matches</p>
        </div>
      </div>
      <div className="h-[320px] w-full">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={chartData} margin={{top:12,right:18,left:-12,bottom:8}}>
            <CartesianGrid stroke="rgba(255,255,255,.08)" vertical={false}/>
            <XAxis dataKey="label" stroke="rgba(255,255,255,.3)" tickLine={false} axisLine={false} minTickGap={24}/>
            <YAxis domain={[low-padding,high+padding]} stroke="rgba(255,255,255,.3)" tickLine={false} axisLine={false}/>
            <Tooltip cursor={{stroke:'rgba(255,255,255,.18)'}} content={({active,payload}:any)=>{const point=payload?.[0]?.payload;if(!active||!point)return null;return <div className="max-w-72 border border-white/15 bg-[#090b0f] p-3 text-xs shadow-2xl"><b className="block text-sm">{point.event}</b><span className="mt-1 block text-white/45">{point.label} · {point.matches} matches</span><span className={`mt-2 block font-mono font-black ${point.change>=0?'text-emerald-400':'text-rose-400'}`}>{point.change>=0?'+':''}{point.change} points · rating {point.rating}</span></div>}}/>
            <Line
              type="monotone"
              dataKey="rating"
              stroke="#ed2b3a"
              strokeWidth={3}
              activeDot={false}
              dot={(props:any)=>(
                <circle
                  cx={props.cx}
                  cy={props.cy}
                  r={selected?.eventId===props.payload.eventId?6:4.5}
                  fill={props.payload.change>=0?'#34d399':'#fb7185'}
                  stroke="#101319"
                  strokeWidth={2}
                  role="button"
                  tabIndex={0}
                  className="cursor-pointer outline-none focus:stroke-white"
                  aria-label={`${props.payload.event}: ${props.payload.change>=0?'gained':'lost'} ${Math.abs(props.payload.change)} points`}
                  onClick={()=>setSelected(props.payload)}
                  onKeyDown={(event:any)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();setSelected(props.payload)}}}
                />
              )}
            />
          </LineChart>
        </ResponsiveContainer>
      </div>
      <p className="mt-3 text-xs text-white/35">Select any point to inspect the tournament. Movement is replayed from the team’s official scored matches and grouped by event.</p>
    </div>
  </article>;
}

function TeamView({ team, goBack, backLabel, openEvent }: { team:any; goBack:()=>void;backLabel:string;openEvent:(event:any)=>void }) {
  const initialCacheKey=teamCacheKey(String(team.number),team.seasonId,team.id);const [history,setHistory]=useState<any>(()=>team.history??teamHistoryCache.get(initialCacheKey)??null);const [historyError,setHistoryError]=useState('');const [retry,setRetry]=useState(0);const winRate=team.matches&&team.record?Math.round((Number(team.record.split('–')[0])/team.matches)*100):0;
  const profile=history?.team??team;
  const seasons=history?Array.from(new Map(history.events.map((event:any)=>[event.seasonId,{id:event.seasonId,name:event.season}])).values()) as {id:number;name:string}[]:[];
  const [selectedSeason,setSelectedSeason]=useState<number|undefined>(seasons[0]?.id);
  useEffect(()=>{const cacheKey=teamCacheKey(String(team.number),team.seasonId,team.id);const cached=team.history??teamHistoryCache.get(cacheKey);setHistory(cached??null);setHistoryError('');if(cached?.seasonGrades)return;let active=true;cachedJson(teamProfileUrl(team.number,team.seasonId,team.id),teamHistoryCache,cacheKey).then((data:any)=>{if(active)setHistory(data)}).catch(error=>{if(active)setHistoryError(error.message||'Team history could not be loaded.')});return()=>{active=false}},[team.number,team.id,team.seasonId,team.history,retry]);
  useEffect(()=>{const requested=Number(team.seasonId)||(team.season==='2025–26 Push Back'?197:team.season==='2026–27 Override'?204:undefined);setSelectedSeason(previous=>previous&&seasons.some(season=>season.id===previous)?previous:requested&&seasons.some(season=>season.id===requested)?requested:seasons[0]?.id)},[team.number,team.seasonId,team.season,history]);
  useEffect(()=>{if(!history||!selectedSeason||(history.loadedSeasonIds??[]).includes(selectedSeason))return;let active=true;const cacheKey=teamCacheKey(String(team.number),selectedSeason,team.id);cachedJson(teamProfileUrl(team.number,selectedSeason,team.id),teamHistoryCache,cacheKey).then((data:any)=>{if(active)setHistory(data)}).catch(error=>{if(active)setHistoryError(error.message)});return()=>{active=false}},[team.number,team.id,selectedSeason,history?.loadedSeasonIds,retry]);
  const seasonEvents=history?history.events.filter((event:any)=>event.seasonId===selectedSeason):[];
  const seasonAwards=history?history.awards.filter((award:any)=>award.seasonId===selectedSeason):[];
  const seasonSkills=history?history.skills.filter((skill:any)=>skill.seasonId===selectedSeason):[];
  const bestDriver=Math.max(0,...seasonSkills.filter((skill:any)=>skill.type==='driver').map((skill:any)=>Number(skill.score)));
  const bestProgramming=Math.max(0,...seasonSkills.filter((skill:any)=>skill.type==='programming').map((skill:any)=>Number(skill.score)));
  const skillEvents=new Map<number,{driver:number;programming:number}>();
  seasonSkills.forEach((skill:any)=>{const score=skillEvents.get(skill.eventId)??{driver:0,programming:0};if(skill.type==='driver')score.driver=Math.max(score.driver,Number(skill.score));if(skill.type==='programming')score.programming=Math.max(score.programming,Number(skill.score));skillEvents.set(skill.eventId,score)});
  const bestCombined=Math.max(0,...[...skillEvents.values()].map(score=>score.driver+score.programming));
  const seasonTrend=history?(history.ratingHistory??[]).filter((point:any)=>point.seasonId===selectedSeason).sort((a:any,b:any)=>String(a.eventDate).localeCompare(String(b.eventDate))):[];
  const seasonGrade=history?.seasonGrades?.[String(selectedSeason)]??profile.grade;
  return <section><div className="border-b border-white/10 bg-[radial-gradient(circle_at_75%_30%,rgba(237,43,58,.14),transparent_35%),#101319]"><div className="mx-auto max-w-[1440px] px-5 py-10 lg:px-8"><button onClick={goBack} className="mb-8 flex items-center gap-2 text-xs font-bold text-white/40 hover:text-white"><ArrowLeft className="h-4 w-4" /> Back to {backLabel}</button><div className="flex flex-col gap-6 sm:flex-row sm:items-end"><div className="grid h-24 w-24 place-items-center border border-white/10 bg-white/[.04] text-3xl font-black text-white/20">{profile.number.slice(-1)}</div><div><p className="text-xs font-black uppercase tracking-[.18em] text-[#ed2b3a]">{history?(profile.active?'Active this season':'Inactive this season'):(team.rank?`Provisional world rank #${team.rank}`:'Loading official team profile')}</p><h1 className="mt-2 text-4xl font-black tracking-[-.04em] sm:text-6xl">{profile.number}</h1><p className="mt-2 text-lg text-white/55">{profile.name} · {profile.region}</p>{profile.organization&&<p className="mt-1 text-sm text-white/35">{profile.organization} · {seasonGrade}</p>}</div><div className="sm:ml-auto sm:text-right"><small className="font-black uppercase tracking-wider text-white/30">{team.rating?'Live VCR rating':'Ranking status'}</small><p className="font-mono text-5xl font-black">{team.rating??'—'}</p><p className="mt-1 text-sm text-white/35">{team.rating?`Confidence ±${team.confidence??'—'}`:'Not rated this season'}</p></div></div></div></div>
    {history?<div className="mx-auto max-w-[1440px] px-5 py-8 lg:px-8">{historyError&&<LoadError message={historyError} retry={()=>{setHistoryError('');setRetry(value=>value+1)}} />}<div className="grid gap-3 border border-white/10 bg-[#101319] p-4 sm:grid-cols-[1fr_3fr] sm:items-end"><FilterSelect label="Team season" value={String(selectedSeason??'')} options={seasons.map(season=>String(season.id))} optionLabels={Object.fromEntries(seasons.map(season=>[String(season.id),season.name]))} onChange={value=>setSelectedSeason(Number(value))} /><p className="pb-2 text-sm text-white/40">Showing official results for {seasons.find(season=>season.id===selectedSeason)?.name??'the selected season'}.</p></div><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Metric label="Status" value={profile.active?'Active':'Inactive'} detail={`${profile.currentSeasonEvents} current-season events`} /><Metric label="Season events" value={String(seasonEvents.length)} detail="Official competitions" /><Metric label="Season awards" value={String(seasonAwards.length)} detail="Official award records" /><Metric label="Seasons found" value={String(profile.seasons)} detail="Complete team history" /></div><SeasonRatingChart data={seasonTrend} onOpenEvent={(point)=>{const event=history.events.find((item:any)=>item.id===point.eventId);if(event)openEvent({...event,date:event.start,end:event.end?.slice(0,10),city:event.location})}}/><article className="mt-6 border border-white/10 bg-[#101319]"><SectionTitle eyebrow="Robot skills" title="Season best skills scores" icon={<Target />} /><div className="grid gap-3 p-5 sm:grid-cols-3"><Metric label="Driver skills" value={bestDriver?String(bestDriver):'—'} detail="Highest official driver score" /><Metric label="Programming skills" value={bestProgramming?String(bestProgramming):'—'} detail="Highest official autonomous score" /><Metric label="Combined skills" value={bestCombined?String(bestCombined):'—'} detail="Best driver + programming at one event" /></div></article><div className="mt-6 grid gap-6 lg:grid-cols-[1.35fr_.65fr]"><article className="border border-white/10 bg-[#101319]"><SectionTitle eyebrow="Competition history" title="Events, qualification and finals" icon={<Trophy />} /><div className="max-h-[720px] overflow-auto">{seasonEvents.map((event:any)=>{const standings=history.rankings.filter((row:any)=>row.eventId===event.id);const eventSkills=history.skills.filter((skill:any)=>skill.eventId===event.id);const driver=Math.max(0,...eventSkills.filter((skill:any)=>skill.type==='driver').map((skill:any)=>Number(skill.score)));const programming=Math.max(0,...eventSkills.filter((skill:any)=>skill.type==='programming').map((skill:any)=>Number(skill.score)));return <div key={event.id} className="border-b border-white/[.07] p-5"><button onClick={()=>openEvent({...event,date:event.start,end:event.end?.slice(0,10),city:event.location})} className="flex w-full justify-between gap-4 text-left hover:text-[#ed2b3a]"><b>{event.name}</b><small className="shrink-0 text-white/35">{event.start?.slice(0,10)}</small></button><p className="mt-1 text-xs text-white/40">{event.location||'Location not listed'}</p><p className="mt-3 text-sm font-bold text-[#ed2b3a]">Finals: {event.elimination||'No elimination result available'}</p>{standings.map((standing:any,index:number)=><p key={`${standing.division}-${index}`} className="mt-2 text-sm">Qualification rank #{standing.rank} · {standing.wins}–{standing.losses}–{standing.ties}<span className="text-white/35">{standing.division?` · ${standing.division}`:''}</span></p>)}<p className="mt-2 text-xs text-white/45">Skills · Driver {driver||'—'} · Programming {programming||'—'} · Combined {driver||programming?driver+programming:'—'}</p></div>})}{!seasonEvents.length&&<Empty text="No official events are available for this season." />}</div></article><article className="border border-white/10 bg-[#101319]"><SectionTitle eyebrow="Official recognition" title="Awards" icon={<Medal />} /><div className="max-h-[720px] overflow-auto">{seasonAwards.map((award:any,index:number)=><button onClick={()=>{const event=history.events.find((item:any)=>item.id===award.eventId);if(event)openEvent({...event,date:event.start,end:event.end?.slice(0,10),city:event.location})}} key={`${award.eventId}-${award.title}-${index}`} className="block w-full border-b border-white/[.07] p-5 text-left hover:bg-white/[.03]"><b>{award.title}</b><p className="mt-1 text-xs text-white/40">{award.event}</p></button>)}{!seasonAwards.length&&<Empty text="No official awards are listed for this season." />}</div></article></div></div>:team.rating?
    <div className="mx-auto max-w-[1440px] px-5 py-8 lg:px-8"><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><Metric label="Season record" value={team.record} detail={`${team.matches ?? 0} scored matches`} /><Metric label="Events processed" value={String(team.events)} detail="Official current-season events" /><Metric label="Scoring estimate" value={team.opr.toFixed(1)} detail="Alliance score share" /><Metric label="Points allowed" value={team.dpr.toFixed(1)} detail="Opponent score share" /><Metric label="Win rate" value={`${winRate}%`} detail="Official scored matches" /></div>
      <div className="mt-6 grid gap-6 lg:grid-cols-[1.2fr_1fr]"><article className="border border-white/10 bg-[#101319]"><SectionTitle eyebrow="Verified identity" title="Official team information" icon={<ShieldCheck />} /><dl className="space-y-4 p-5 text-sm">{[['Team number',team.number],['Official team name',team.name],['Organization',team.organization||'Not listed'],['Robot name',team.robot||'Not listed'],['Grade level',team.grade||'Not listed'],['Location',team.region],['Ranking season',team.season||'2026–27 Override']].map(([label,value])=><div key={label} className="flex justify-between gap-6 border-b border-white/[.07] pb-3"><dt className="text-white/40">{label}</dt><dd className="text-right font-bold">{value}</dd></div>)}</dl></article><article className="border border-white/10 bg-[#101319]"><SectionTitle eyebrow="Rating status" title="Provisional VCR coverage" icon={<Gauge />} /><div className="p-5 text-sm leading-relaxed text-white/45"><p>This profile is built from real Event.VEX match scores for the {team.season||'2026–27 Override'} season. The current rating applies opponent adjustment, margin of victory, chronological processing and a conservative confidence deduction.</p><p className="mt-4">Contribution, autonomous and finish components are not displayed until their source data is complete enough to avoid invented precision.</p><div className="mt-5 border-l-2 border-emerald-400 bg-emerald-400/[.06] p-4 text-emerald-100">{team.matches} official matches are currently included for this team.</div></div></article></div>
    </div>:historyError?<div className="mx-auto max-w-[1440px] px-5 py-8 lg:px-8"><div className="border border-rose-400/25 bg-rose-400/[.05] p-6"><p className="text-sm text-rose-200">{historyError}</p><button onClick={()=>{teamHistoryCache.delete(initialCacheKey);setRetry(value=>value+1)}} className="mt-4 border border-white/15 px-4 py-2 text-xs font-black uppercase tracking-wider hover:bg-white hover:text-black">Retry</button></div></div>:<div className="mx-auto max-w-[1440px] px-5 py-8 lg:px-8"><Empty text="Loading team history…" /></div>}</section>;
}

function PageHead({ eyebrow, title, copy }: {eyebrow:string;title:string;copy:string}) { return <div className="max-w-3xl"><p className="text-xs font-black uppercase tracking-[.18em] text-[#ed2b3a]">{eyebrow}</p><h1 className="mt-2 text-4xl font-black tracking-[-.04em] sm:text-5xl">{title}</h1><p className="mt-3 max-w-2xl text-sm leading-relaxed text-white/45">{copy}</p></div>; }
function SectionTitle({ eyebrow, title, icon }: {eyebrow:string;title:string;icon:React.ReactNode}) { return <div className="flex items-center justify-between border-b border-white/10 px-5 py-4"><div><p className="text-[10px] font-bold uppercase tracking-[.18em] text-[#ed2b3a]">{eyebrow}</p><h2 className="mt-1 text-xl font-black">{title}</h2></div><span className="text-white/25 [&_svg]:h-5 [&_svg]:w-5">{icon}</span></div>; }
function Metric({ label, value, detail }: {label:string;value:string;detail:string}) { return <div className="border border-white/10 bg-[#101319] p-5"><small className="font-black uppercase tracking-wider text-white/30">{label}</small><p className="mt-2 font-mono text-2xl font-black">{value}</p><small className="mt-1 block text-white/35">{detail}</small></div>; }
function StatFeature({ icon, title, copy }: {icon:React.ReactNode;title:string;copy:string}) { return <article className="border-t border-white/15 pt-5"><span className="text-[#ed2b3a] [&_svg]:h-5 [&_svg]:w-5">{icon}</span><h3 className="mt-4 font-black">{title}</h3><p className="mt-2 text-sm leading-relaxed text-white/40">{copy}</p></article>; }
function Empty({ text }: {text:string}) { return <div className="grid min-h-48 place-items-center border border-dashed border-white/15 bg-white/[.02] p-8 text-center"><div><CircleDot className="mx-auto h-7 w-7 text-white/20" /><p className="mt-3 text-sm text-white/40">{text}</p></div></div>; }
function FilterInput({ value, onChange, placeholder, icon }: {value:string;onChange:(value:string)=>void;placeholder:string;icon?:React.ReactNode}) { return <label className="relative">{icon && <span className="absolute left-3 top-3 text-white/35 [&_svg]:h-4 [&_svg]:w-4">{icon}</span>}<input value={value} onChange={event=>onChange(event.target.value)} placeholder={placeholder} aria-label={placeholder} className={`h-10 w-full border border-white/10 bg-black/20 pr-3 text-sm outline-none placeholder:text-white/30 focus:border-white/30 ${icon ? 'pl-9' : 'pl-3'}`} /></label>; }
function FilterSelect({ label, value, options, onChange, className='', allLabel, optionLabels={} }: {label:string;value:string;options:string[];onChange:(value:string)=>void;className?:string;allLabel?:string;optionLabels?:Record<string,string>}) { return <NativeSelect value={value} onChange={event=>onChange(event.target.value)} className={`w-full [&_select]:h-10 [&_select]:rounded-none [&_select]:border-white/10 [&_select]:bg-black/20 ${className}`} aria-label={label}>{options.map(option=><NativeSelectOption key={option} value={option}>{optionLabels[option]??(option === 'All' ? (allLabel ?? `All ${label.toLowerCase()}s`) : option)}</NativeSelectOption>)}</NativeSelect>; }

function seasonYearLabel(name:string='') { const match=name.match(/(20\d{2})\s*[-–]\s*(20\d{2}|\d{2})/);return match?`${match[1]}–${match[2].slice(-2)}`:'—'; }
function LoadError({message,retry}:{message:string;retry:()=>void}) {return <div role="alert" className="my-4 border border-rose-400/30 bg-rose-400/5 p-5"><p className="text-sm text-rose-200">{message}</p><button onClick={retry} className="mt-3 border border-white/20 px-4 py-2 text-sm font-bold hover:bg-white hover:text-black">Retry</button></div>;}

function finalistDivisions(division:any,divisions:any[]) {
  const first=(division.matches??[]).find((match:any)=>Number(match.round)===5);
  return [...(first?.alliances??[])].sort((a:any,b:any)=>(a.color==='red'?0:1)-(b.color==='red'?0:1)).map((alliance:any)=>{
    const ids=new Set((alliance.teams??[]).map((entry:any)=>entry.team?.id));
    return divisions.find((other:any)=>other.id!==division.id&&(other.matches??[]).some((match:any)=>(match.alliances??[]).some((entry:any)=>(entry.teams??[]).some((team:any)=>ids.has(team.team?.id)))))?.name??'';
  });
}
